-- Execute no SQL Editor do Supabase. Cada conta cria seu escritório próprio.
create extension if not exists pgcrypto;
create table if not exists public.offices (id uuid primary key default gen_random_uuid(), name text not null, owner_id uuid not null references auth.users(id), created_at timestamptz not null default now());
create table if not exists public.memberships (office_id uuid not null references public.offices(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','admin','member')), primary key(office_id,user_id));
create or replace function public.is_office_member(p_office uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.memberships where office_id=p_office and user_id=(select auth.uid())) $$;
create or replace function public.is_office_admin(p_office uuid) returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.memberships where office_id=p_office and user_id=(select auth.uid()) and role in ('owner','admin')) $$;
create or replace function public.create_office(p_name text) returns uuid language plpgsql security definer set search_path = '' as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'Autenticação obrigatória'; end if; if length(trim(p_name)) < 2 then raise exception 'Nome inválido'; end if; insert into public.offices(name,owner_id) values(trim(p_name),auth.uid()) returning id into v_id; insert into public.memberships(office_id,user_id,role) values(v_id,auth.uid(),'owner'); return v_id; end $$;
revoke all on function public.create_office(text) from public;
grant execute on function public.create_office(text) to authenticated;
create table if not exists public.clients (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.offices(id) on delete cascade, name text not null, email text, phone text, notes text, created_at timestamptz not null default now());
create table if not exists public.cases (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.offices(id) on delete cascade, client_id uuid references public.clients(id) on delete set null, title text not null, cnj text, opposing_party text, court text, unit text, practice_area text, phase text, created_at timestamptz not null default now());
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.offices(id) on delete cascade, client_id uuid references public.clients(id) on delete set null, case_id uuid references public.cases(id) on delete set null, title text not null, description text, status text not null default 'Novas demandas' check(status in ('Novas demandas','A analisar','Em andamento','Aguardando documentos','Aguardando cliente ou terceiro','Em revisão','Concluídas')), priority text not null default 'Normal' check(priority in ('Baixa','Normal','Alta','Urgente')), due_date date, created_at timestamptz not null default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(), office_id uuid not null references public.offices(id) on delete cascade, client_id uuid references public.clients(id) on delete set null, case_id uuid references public.cases(id) on delete set null, title text not null, kind text not null check(kind in ('Audiência','Prazo judicial','Prazo legal','Prazo administrativo','Prazo interno','Reunião','Atendimento','Diligência','Outro')), starts_at timestamptz not null, ends_at timestamptz, location text, notes text, created_at timestamptz not null default now());
create index if not exists idx_clients_office on public.clients(office_id);
create index if not exists idx_cases_office on public.cases(office_id);
create index if not exists idx_tasks_office_status on public.tasks(office_id,status);
create index if not exists idx_events_office_start on public.events(office_id,starts_at);
alter table public.offices enable row level security;
alter table public.memberships enable row level security;
create policy offices_select on public.offices for select to authenticated using (public.is_office_member(id));
create policy memberships_select on public.memberships for select to authenticated using (public.is_office_member(office_id));
-- Associação de membros deve ser feita por fluxo administrativo seguro futuro.
do $$ declare t text; begin foreach t in array array['clients','cases','tasks','events'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for select to authenticated using (public.is_office_member(office_id))',t||'_select',t); execute format('create policy %I on public.%I for insert to authenticated with check (public.is_office_member(office_id))',t||'_insert',t); execute format('create policy %I on public.%I for update to authenticated using (public.is_office_member(office_id)) with check (public.is_office_member(office_id))',t||'_update',t); execute format('create policy %I on public.%I for delete to authenticated using (public.is_office_member(office_id))',t||'_delete',t); end loop; end $$;
